import {PRODUCT_DB_NAME} from './app-storage.js';
export const BODY={neck:'Szyja',chest:'Klatka',waist:'Talia',abdomen:'Brzuch',hips:'Biodra',thighLeft:'Udo lewe',thighRight:'Udo prawe',calfLeft:'Łydka lewa',calfRight:'Łydka prawa',armLeft:'Ramię lewe',armRight:'Ramię prawe'};
const finite=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;
export function validateMeasurement(row){if(!row||typeof row.id!=='string'||!/^[\w-]{1,100}$/.test(row.id)||!['weight','pressure','body'].includes(row.type)||!/^\d{4}-\d\d-\d\d$/.test(row.date)||!Number.isFinite(Date.parse(row.date))||new Date(row.date).toISOString().slice(0,10)!==row.date||!/^([01]\d|2[0-3]):[0-5]\d$/.test(row.time)||typeof row.note!=='string'||row.note.length>1000)throw new Error('Sprawdź datę, godzinę i wartości pomiaru.');const values={};if(row.type==='weight'){if(!finite(row.values?.kg,1,600))throw new Error('Podaj wagę 1–600 kg.');values.kg=row.values.kg;}if(row.type==='pressure'){for(const [k,min,max]of [['systolic',30,350],['diastolic',20,250],['pulse',20,300]]){if(!finite(row.values?.[k],min,max))throw new Error('Sprawdź wartości ciśnienia i tętna.');values[k]=row.values[k];}if(!['morning','noon','evening','other'].includes(row.period))throw new Error('Wybierz porę.');}if(row.type==='body'){for(const k of Object.keys(row.values??{})){if(!Object.hasOwn(BODY,k)||!finite(row.values[k],1,350))throw new Error('Obwody muszą wynosić 1–350 cm.');values[k]=row.values[k];}if(!Object.keys(values).length)throw new Error('Podaj przynajmniej jeden obwód.');}return {id:row.id,type:row.type,date:row.date,time:row.time,note:row.note,values,...(row.type==='pressure'?{period:row.period}:{})};}
export function weightTrend(rows){const weights=rows.filter(r=>r.type==='weight').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));let first=0,sum=0;return weights.map((r,i)=>{sum+=r.values.kg;const start=Date.parse(r.date)-6*86400000;while(first<i&&Date.parse(weights[first].date)<start)sum-=weights[first++].values.kg;return {...r,average:sum/(i-first+1)};});}
export function createProgressStore(){let db;const open=()=>db??=new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){reject(new Error('Pamięć pomiarów jest niedostępna w tej przeglądarce.'));return;}const q=indexedDB.open(PRODUCT_DB_NAME+'-progress',1);q.onupgradeneeded=()=>{for(const n of ['measurements','sessions','photos'])q.result.createObjectStore(n,{keyPath:'id'});};q.onsuccess=()=>{q.result.onversionchange=()=>{q.result.close();db=null;};resolve(q.result);};q.onerror=()=>reject(q.error);q.onblocked=()=>reject(new Error('Zamknij inne karty przed aktualizacją danych.'));});async function snapshot(){const d=await open();return new Promise((resolve,reject)=>{const t=d.transaction(['measurements','sessions','photos'],'readonly'),out={};for(const n of ['measurements','sessions','photos']){const q=t.objectStore(n).getAll();q.onsuccess=()=>out[n]=q.result;}t.oncomplete=()=>resolve(out);t.onabort=t.onerror=()=>reject(t.error);});}async function replace(state){const d=await open();return new Promise((resolve,reject)=>{const t=d.transaction(['measurements','sessions','photos'],'readwrite');try{for(const n of ['measurements','sessions','photos']){const s=t.objectStore(n);s.clear();for(const row of state[n])s.put(row);}}catch(e){t.abort();reject(e);}t.oncomplete=resolve;t.onabort=t.onerror=()=>reject(t.error);});}async function change(fn){const d=await open();return new Promise((resolve,reject)=>{const t=d.transaction(['measurements','sessions','photos'],'readwrite'),state={};let left=3;for(const n of ['measurements','sessions','photos']){const q=t.objectStore(n).getAll();q.onsuccess=()=>{state[n]=q.result;if(--left===0)try{fn(state);for(const name of Object.keys(state)){const store=t.objectStore(name);store.clear();for(const r of state[name])store.put(r);}}catch(e){t.abort();reject(e);}};}t.oncomplete=resolve;t.onabort=t.onerror=()=>reject(t.error);});}return {snapshot,replace,change,async save(row){row=validateMeasurement(row);const d=await open();await ne