export function imageDimensions(bytes,type){const d=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let width,height;if(type==='image/png'&&bytes.length>=24&&d.getUint32(0)===0x89504e47&&d.getUint32(4)===0x0d0a1a0a){width=d.getUint32(16);height=d.getUint32(20);}else if(type==='image/jpeg'&&bytes[0]===255&&bytes[1]===216){let i=2;while(i+8<bytes.length){if(bytes[i]!==255)break;const marker=bytes[i+1],length=d.getUint16(i+2);if(length<2||i+length+2>bytes.length)break;if([192,193,194,195,197,198,199,201,202,203,205,206,207].includes(marker)){height=d.getUint16(i+5);width=d.getUint16(i+7);break;}i+=length+2;}}if(!width||!height||width*height>40e6||width>12000||height>12000)throw new Error('Nieprawidłowy obraz lub za duża rozdzielczość (limit 40 MP).');return {width,height};}
